def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 9 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.append((color, cells))
    # Recolor the dominant irregular central mass to the accent color used by
    # the matching small motifs.
    candidates = [(color, cells) for color, cells in components if color == 6]
    if candidates:
        _, cells = max(candidates, key=lambda item: len(item[1]))
        if len(cells) > 10:
            for r, c in cells:
                out[r][c] = 1
    return out

