 "content": "from collections import deque

def _shape(cells):
    pts = list(cells)
    variants = []
    for flip in (1, -1):
        for rot in range(4):
            transformed = []
            for y, x in pts:
                x *= flip
                for _ in range(rot):
                    y, x = x, -y
                transformed.append((y, x))
            min_y = min(y for y, x in transformed)
            min_x = min(x for y, x in transformed)
            variants.append(tuple(sorted((y-min_y, x-min_x) for y, x in transformed)))
    return min(variants)

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 9 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append((color, cells))
    # An identical motif is repeated in two colors. Recolor the first instance
    # to the color of the later matching instance.
    by_shape = {}
    for color, cells in comps:
        key = _shape(cells)
        if key in by_shape and by_shape[key][0] != color:
            target = color
            source_cells = by_shape[key][1]
            out = [row[:] for row in grid]
            for r, c in source_cells:
                out[r][c] = target
            return out
        by_shape[key] = (color, cells)
    return [row[:] for row in grid]

if __name__ == '__main__':
    pass
