 "content": "from collections import deque

def _shape(cells):
    variants = []
    for flip in (1, -1):
        for rot in range(4):
            pts = []
            for y, x in cells:
                x *= flip
                for _ in range(rot):
                    y, x = x, -y
                pts.append((y, x))
            min_y = min(y for y, x in pts)
            min_x = min(x for y, x in pts)
            variants.append(tuple(sorted((y-min_y, x-min_x) for y, x in pts)))
    return min(variants)

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 9 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append((color, cells))
    first = {}
    recolor = {}
    for color, cells in comps:
        if len(cells) < 2:
            continue
        key = _shape(cells)
        if key not in first:
            first[key] = (color, cells)
        elif first[key][0] != color:
            old_color, old_cells = first[key]
            recolor.update({p: color for p in old_cells})
    out = [row[:] for row in grid]
    for (r, c), color in recolor.items():
        out[r][c] = color
    return out

