 "content": "from collections import deque

def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 9) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append((color, cells))
    return comps

def _norm(cells):
    mr = min(r for r,c in cells)
    mc = min(c for r,c in cells)
    return frozenset((r-mr,c-mc) for r,c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    comps = _components(grid)
    # Recolor the isolated component whose shape is duplicated by another color.
    for i, (col, cells) in enumerate(comps):
        shape = _norm(cells)
        matches = [(other_col, other_cells) for j, (other_col, other_cells) in enumerate(comps)
                   if j != i and other_col != col and _norm(other_cells) == shape]
        if matches:
            target_col, _ = matches[0]
            for r, c in cells:
                out[r][c] = target_col
            return out
    return out
