 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Recolor the component with the repeated distinctive shape. Ignore the
    # background and find copies of a component shape among colored objects.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 9) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            minr = min(y for y,x in cells)
            minc = min(x for y,x in cells)
            shape = frozenset((y-minr,x-minc) for y,x in cells)
            comps.append((color, cells, shape))
    # In these examples the target is the first occurrence of an exact
    # same-colored-shape correspondence, recolored to the other component's color.
    for i, (color, cells, shape) in enumerate(comps):
        for j, (other_color, other_cells, other_shape) in enumerate(comps):
            if i != j and color != other_color and shape == other_shape:
                for y, x in cells:
                    out[y][x] = other_color
                return out
    return out
